```java
public enum StatusType {
    ENABLE,
    DISABLE,
    DELETED;

    public static StatusType fromString(String status) {
        switch (status.toUpperCase()) {
            case "ENABLE":
                return ENABLE;
            case "DISABLE":
                return DISABLE;
            case "DELETED":
                return DELETED;
            default:
                throw new IllegalArgumentException("有効ではない状態値です。");
        }
    }
}
